fn inl_product_xyz<'a>(ctx: &'a Ctx, a: Vec<'a>, b: Vec<'a>) -> f64 {
    let mut a = a;
    let mut b = b;
    return (fp::fadds(
        fp::fadds(fp::fmuls((a).x(), (b).x()), fp::fmuls((a).y(), (b).y())),
        fp::fmuls((a).z(), (b).z()),
    ));
}

fn inl_itzako_sqrtf<'a>(ctx: &'a Ctx, x: f64) -> f64 {
    let mut x = x;
    let mut y: f64 = 0.0;
    if x > 0.0 {
        let mut guess: f64 = fp::frsqrte(x);
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(fp::fmul(guess, guess), x, 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(fp::fmul(guess, guess), x, 3.0)),
        );
        guess = fp::fmul(
            fp::fmul(0.5, guess),
            (fp::fnmsub(fp::fmul(guess, guess), x, 3.0)),
        );
        y = fp::frsp((fp::fmul(x, guess)));
        return y;
    }
    return x;
}

fn inl_return_sqrt_value3<'a>(ctx: &'a Ctx, v: Vec<'a>) -> f64 {
    let mut v = v;
    return inl_itzako_sqrtf(ctx, inl_product_xyz(ctx, v, v));
}

